<script setup>
import ApplicationContext from './ApplicationContext.vue'
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, errorMessage, localTime } from './api'
import { reviewedScore } from './performance-score'
import { duration } from './employee-utils'
const props=defineProps({admin:Boolean,people:{type:Array,default:()=>[]}})
function monday(date=new Date().toISOString().slice(0,10)){const d=new Date(date+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return d.toISOString().slice(0,10)}
const week=ref(monday()),employee=ref(props.people.find(p=>!p.role||p.role==='employee')?.id || ''),report=ref(null),busy=ref(false),error=ref(''),message=ref(''),allOpen=ref(false),board=ref(false),rankings=ref([]),rankPage=ref(1),rankLast=ref(1)
const preset=ref('agency'),presetConfirmed=ref(false)
async function applyPreset(){if(!presetConfirmed.value)return;if(await mutate('/api/admin/performance/apply-preset',{user_id:employee.value,preset:preset.value},'Preset applied. Existing custom rules were preserved.'))presetConfirmed.value=false}
const family=ref('general'),domainRule=reactive({domain:'',category:'neutral',reason:''})
function workPercent(value){return value == null ? 'No categorized data' : Number(value).toLocaleString(undefined,{maximumFractionDigits:2})+'%'}
const task=reactive({kind:'task',title:'',criteria:'',due_date:new Date().toISOString().slice(0,10),points:1})
const context=reactive({work_date:new Date().toISOString().slice(0,10),kind:'meeting',minutes:60,note:''})
const review=reactive({collaboration:80,manager_note:'',confirmed:false}),rule=reactive({app_name:'',category:'neutral',reason:''}),actions=reactive({})
let generation=0
const tasks=computed(()=>allOpen.value&&!props.admin?report.value?.open_tasks || []:report.value?.tasks || [])
const preview=computed(()=>{const m=report.value?.metrics;if(!report.value?.eligible)return null;return reviewedScore(m,review.collaboration).toFixed(2)})
const totals=computed(()=>(report.value?.daily || []).reduce((a,d)=>({active:a.active+(d.active_seconds||0),idle:a.idle+(d.idle_seconds||0),legacy:a.legacy+(d.legacy_seconds||0)}),{active:0,idle:0,legacy:0}))
function action(item){return actions[item.id] || (actions[item.id]={evidence:item.evidence || '',status:item.status==='submitted'?'accepted':'cancelled',quality:80,review_note:''})}
async function load(){const current=++generation;busy.value=true;error.value='';report.value=null;review.confirmed=false;Object.keys(actions).forEach(k=>delete actions[k]);try{if(board.value){const {data}=await api.get('/api/admin/performance/rankings',{params:{week:week.value,page:rankPage.value}});if(current===generation){rankings.value=data.data;rankLast.value=data.last_page}}else if(!props.admin||employee.value){const {data}=await api.get(props.admin?'/api/admin/performance':'/local/performance',{params:{week:week.value,...(props.admin?{user_id:employee.value}:{})}});if(current===generation)report.value=data}}catch(e){if(current===generation)error.value=errorMessage(e)}finally{if(current===generation)busy.value=false}}
async function mutate(path,data,success){busy.value=true;error.value='';message.value='';try{await api.post(path,data);message.value=success;await load();return true}catch(e){error.value=errorMessage(e);return false}finally{busy.value=false}}
async function createTask(){if(await mutate('/api/admin/performance/tasks',{...task,user_id:employee.value},'Work assigned. Select its due week to review it.')){task.title='';task.criteria=''}}
async function submit(item){await mutate('/local/task-submit',{id:item.id,revision:item.revision,evidence:action(item).evidence},'Submitted for manager review.')}
async function decide(item){const a=action(item);await mutate('/api/admin/performance/tasks/'+item.id+'/review',{revision:item.revision,...a,quality:a.status==='accepted'?a.quality:null},'Task review saved.')}
async function explain(){if(await mutate('/local/work-context',{...context},'Context saved. It does not automatically change recorded hours or a published score.'))context.note=''}
async function publish(){await mutate('/api/admin/performance/publish',{user_id:employee.value,week:week.value,fingerprint:report.value.fingerprint,...review},'Reviewed result published to the employee. This snapshot is now final.')}
async function classify(){await mutate('/api/admin/performance/app-rule',{user_id:employee.value,...rule},'Classification saved for this department and job role. It does not affect scores.')}
async function classifyDomain(){await mutate('/api/admin/performance/domain-rule',{user_id:employee.value,...domainRule},'Exact-domain classification saved.')}
async function applyDefaults(){await mutate('/api/admin/performance/app-defaults',{user_id:employee.value,family:family.value},'Defaults applied to missing app rules; existing choices preserved.')}
function selectionChanged(){generation++;report.value=null;busy.value=false;review.manager_note='';review.collaboration=80;review.confirmed=false;rule.app_name='';rule.reason='';rankPage.value=1}
function changeBoard(value){board.value=value;rankPage.value=1;load()}
onMounted(load);onUnmounted(()=>generation++)
</script>
<template><section class="performance-workspace">
<div class="card"><h2>{{admin?'Goals, evidence & team reviews':'Your work, with context'}}</h2><p class="muted">Outcomes and quality lead. Computer activity is supporting information.</p>
<div v-if="admin" class="personnel-tabs"><button :disabled="busy" :class="{primary:!board}" @click="changeBoard(false)">Employee review</button><button :disabled="busy" :class="{primary:board}" @click="changeBoard(true)">Reviewed rankings</button></div>
<form class="form-grid" @submit.prevent="load"><label v-if="admin&&!board">Employee<select v-model="employee" required @change="selectionChanged" :disabled="busy"><option disabled value="">Choose employee</option><option v-for="p in people.filter(p=>!p.role||p.role==='employee')" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Week starting Monday (UTC)<input v-model="week" type="date" required @change="selectionChanged" :disabled="busy"></label><div class="inline-actions"><button class="primary" :disabled="busy">Load week</button></div></form>
<details><summary>How scoring works</summary><p>Completion 40% · quality 30% · deadlines 20% · collaboration 10%. Task points (1–10) reflect agreed scope. Completion and deadlines include all non-cancelled tasks due in the selected week; points-weighted quality averages accepted work only. Deadlines use employee submission time. Managers assess quality and collaboration against evidence.</p><p>A full, closed Monday–Sunday UTC week since account creation, at least three tasks, an accepted result and a manager review are required. Rankings need at least two published reviews in the same department and job title. Ties share a rank. Unreviewed employees are not ranked.</p><p>Work App % is informational only; unclassified time is excluded. Idle time, application categories and screenshots never change scores. Reading, meetings and calls may look idle. Published reviews preserve the evidence as it was reviewed; later changes do not rewrite them.</p></details></div>
<p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="busy" role="status">Loading or saving…</p>
<section v-if="board" class="card"><h2>Published rankings · {{week}}</h2><p class="muted">Compare only employees in the same cohort. Missing employees have no published review for this week.</p><div class="table-scroll"><table><thead><tr><th>Department / role</th><th>Employee</th><th>Rank</th><th>Reviewed score</th><th>Published</th></tr></thead><tbody><tr v-for="row in rankings" :key="row.user_id"><td>{{row.cohort}}</td><td>{{row.name}}</td><td>{{row.rank ?? 'Not enough peers'}}</td><td>{{Number(row.score).toFixed(2)}} / 100</td><td>{{localTime(row.published_at)}}</td></tr><tr v-if="!rankings.length"><td colspan="5">No reviewed results for this week.</td></tr></tbody></table></div><div class="pagination"><button :disabled="busy||rankPage<=1" @click="rankPage--;load()">Previous</button><span>{{rankPage}} / {{rankLast}}</span><button :disabled="busy||rankPage>=rankLast" @click="rankPage++;load()">Next</button></div></section>
<template v-if="report&&!board">
<div class="stats-grid"><article class="stat"><span>Accepted work</span><strong>{{report.metrics.accepted_count}} / {{report.metrics.task_count}}</strong><small>Tasks due this week, excluding cancelled</small></article><article class="stat"><span>Time in work apps</span><strong>{{workPercent(report.work_app_percent)}}</strong><small>Estimated from role rules. Not a productivity score.</small></article><article class="stat"><span>Completion</span><strong>{{report.metrics.completion ?? '—'}}%</strong><small>Scope-weighted accepted outcomes</small></article><article class="stat"><span>Quality</span><strong>{{report.metrics.quality ?? '—'}}</strong><small>Manager-reviewed accepted work</small></article></div><details class="card"><summary>Computer activity context</summary><p>Active: {{duration(totals.active)}} · Idle: {{duration(totals.idle)}} · Legacy: {{duration(totals.legacy)}}. These are not measures of productivity.</p></details>
<section v-if="report.published" class="card"><div class="eyebrow">MANAGER-REVIEWED RESULT</div><h2>{{report.published.score}} / 100 <span class="pill neutral">{{report.published.rank?'Rank '+report.published.rank+' of '+report.published.peer_count:'Not enough reviewed peers to rank'}}</span></h2><p>{{report.published.cohort_label}} · Published {{localTime(report.published.published_at)}}</p><p class="performance-note">{{report.published.manager_note}}</p><p>Completion {{report.published.snapshot.metrics.completion}} · Quality {{report.published.snapshot.metrics.quality}} · Deadlines {{report.published.snapshot.metrics.deadlines}} · Collaboration {{report.published.collaboration}}</p><p>Time in work apps at publication: <strong>{{report.published.snapshot.work_app_percent === undefined ? "Not recorded in this older review" : workPercent(report.published.snapshot.work_app_percent)}}</strong><br><small>Estimated from role rules. Not a productivity score.</small></p><details><summary>Evidence included in the published review</summary><ul><li v-for="t in report.published.snapshot.tasks" :key="t.id">{{t.title}} — {{t.status}} · {{t.points}} points · Quality {{t.quality ?? 'not assessed'}}<p class="performance-note">{{t.evidence || 'No submission'}}<br>{{t.review_note}}</p></li></ul><p v-for="n in report.published.snapshot.explanations" :key="n.id" class="performance-note">{{n.work_date}} · {{n.kind}} · {{n.minutes}} minutes: {{n.note}}</p></details></section>
<section v-else class="card"><h2>{{report.eligible?'Ready for manager review':'Insufficient data for a reviewed score'}}</h2><p>{{report.cohort.label}}</p><ul v-if="report.reasons.length"><li v-for="reason in report.reasons" :key="reason">{{reason}}</li></ul><p v-else>A score is published only after a manager reviews outcomes and employee context.</p></section>
<section v-if="admin" class="card"><details><summary>Assign a task or goal</summary><form @submit.prevent="createTask"><div class="form-grid"><label>Type<select v-model="task.kind"><option value="task">Task</option><option value="goal">Goal</option></select></label><label>Due date (end of day, UTC)<input v-model="task.due_date" type="date" required></label><label>Scope points (1–10)<input v-model.number="task.points" type="number" min="1" max="10" required></label></div><label>Title<input v-model.trim="task.title" maxlength="180" required></label><label>Success criteria<textarea v-model.trim="task.criteria" minlength="10" maxlength="2000" required placeholder="What outcome and quality will count as accepted?"></textarea></label><button class="primary" :disabled="busy">Assign work</button></form></details></section>
<section class="card"><div class="card-heading"><h2>{{allOpen&&!admin?'Open work across all weeks':'Tasks due this week'}}</h2><label v-if="!admin" class="check-label"><input v-model="allOpen" type="checkbox">Show open work</label></div><p v-if="allOpen&&!admin" class="muted">Showing the earliest {{report.open_tasks.length}} of {{report.open_count}} open tasks. Select a due week to see all tasks for that week.</p><p v-if="!tasks.length">No tasks in this view.</p><article v-for="item in tasks" :key="item.id" class="performance-task"><div class="card-heading"><h3>{{item.title}}</h3><span class="pill neutral">{{item.status.replaceAll('_',' ')}}</span></div><small>{{item.kind}} · Due {{item.due_date}} UTC · {{item.points}} points</small><p class="performance-note">{{item.criteria}}</p><p v-if="item.evidence" class="performance-note"><strong>Employee evidence</strong><br>{{item.evidence}}<br><small>Submitted {{localTime(item.submitted_at)}}</small></p><p v-if="item.review_note" class="performance-note"><strong>Manager feedback</strong><br>{{item.review_note}}<br><small v-if="item.quality!==null">Quality: {{item.quality}} / 100</small></p>
<form v-if="!admin&&['assigned','changes_requested'].includes(item.status)" @submit.prevent="submit(item)"><label>Result and supporting evidence<textarea v-model.trim="action(item).evidence" minlength="10" maxlength="2000" required placeholder="Describe the result; include reference links if helpful."></textarea></label><button :disabled="busy" class="primary">Submit for review</button></form>
<form v-if="admin&&!['accepted','cancelled'].includes(item.status)" @submit.prevent="decide(item)"><div class="form-grid"><label>Decision<select v-model="action(item).status"><option v-if="item.status==='submitted'" value="accepted">Accept result</option><option v-if="item.status==='submitted'" value="changes_requested">Request changes</option><option value="cancelled">Cancel task</option></select></label><label v-if="action(item).status==='accepted'">Quality (0–100)<input v-model.number="action(item).quality" type="number" min="0" max="100" required></label></div><label>Decision evidence / reason<textarea v-model.trim="action(item).review_note" minlength="10" maxlength="2000" required></textarea></label><button :disabled="busy">Save task review</button><p class="small muted">Accepted and cancelled tasks are final. Cancelled work is excluded from the score.</p></form></article></section>
<section class="card"><h2>Employee context</h2><p class="muted">Self-reported context supports review. These minutes are not added to active hours or counted in the score.</p><p v-if="!report.explanations.length">No context notes for this week.</p><article v-for="note in report.explanations" :key="note.id" class="performance-task"><strong>{{note.work_date}} · {{note.kind}} · {{note.minutes}} minutes</strong><p class="performance-note">{{note.note}}</p></article><form v-if="!admin" @submit.prevent="explain"><div class="form-grid"><label>Date (UTC)<input v-model="context.work_date" type="date" required></label><label>Activity<select v-model="context.kind"><option value="meeting">Meeting or call</option><option value="research">Reading or research</option><option value="offline">Offline work</option><option value="context">Other context / correction</option></select></label><label>Minutes<input v-model.number="context.minutes" type="number" min="1" max="1440" required></label></div><label>Explanation<textarea v-model.trim="context.note" minlength="10" maxlength="1000" required></textarea></label><button :disabled="busy">Add context</button></form></section>
<ApplicationContext :context="report.application_context" /><section class="card"><h2>Application context</h2><p class="muted">Top 20 foreground applications by sample count, not time spent. Classification applies to {{report.cohort.label}} and never changes a score.</p><div class="table-scroll"><table><thead><tr><th>Application</th><th>Samples</th><th>Context</th><th>Reason</th></tr></thead><tbody><tr v-for="app in report.apps" :key="app.app_name"><td>{{app.app_name}}</td><td>{{app.samples}}</td><td>{{app.category.replaceAll('_',' ')}}</td><td>{{app.reason}}</td></tr><tr v-if="!report.apps.length"><td colspan="4">No retained samples for this week.</td></tr></tbody></table></div><form v-if="admin" @submit.prevent="applyPreset"><label>Apply a preset for this role<select v-model="preset" @change="presetConfirmed=false"><option value="agency">Agency</option><option value="devshop">Devshop</option><option value="office">Office</option></select></label><p>This adds suggested rules. Existing custom rules are preserved. Review before relying on them.</p><label class="check-label"><input v-model="presetConfirmed" type="checkbox" required>I confirm these suggestions should be added for this role.</label><button :disabled="busy || !report.cohort.key || !presetConfirmed">Apply preset</button></form><details v-if="admin"><summary>Apply suggested app defaults</summary><form @submit.prevent="applyDefaults"><label>Job family<select v-model="family"><option value="general">General</option><option value="engineering">Engineering</option><option value="office">Office</option><option value="design">Design</option></select></label><p>Review defaults for this role. Categories vary by template; browser use can include personal activity. Review suggested rules before relying on them. Existing rules are preserved.</p><button :disabled="busy || !report.cohort.key">Apply defaults to this role</button></form></details><details v-if="admin"><summary>Classify an application for this role</summary><form @submit.prevent="classify"><div class="form-grid"><label>Exact application name<input v-model.trim="rule.app_name" maxlength="160" required placeholder="msedge.exe"></label><label>Category<select v-model="rule.category"><option value="work_related">Work related</option><option value="neutral">Neutral</option><option value="review_context">Review with employee context</option></select></label></div><label>Reason<input v-model.trim="rule.reason" minlength="10" maxlength="500" required></label><button :disabled="busy || !report.cohort.key">Save role classification</button></form></details></section>
<section class="card"><h2>Observed domains</h2><p>Exact hostnames only; subdomains require separate rules. Domain categories provide context and never change scores.</p><div class="table-scroll"><table><thead><tr><th>Domain</th><th>Observed samples</th><th>Category</th><th>Reason</th></tr></thead><tbody><tr v-for="d in report.application_context?.domains||[]" :key="d.domain"><td>{{d.domain}}</td><td>{{d.samples}}</td><td>{{d.category.replaceAll('_',' ')}}</td><td>{{d.reason}}</td></tr></tbody></table></div><form v-if="admin" @submit.prevent="classifyDomain"><label>Exact hostname<input v-model.trim="domainRule.domain" maxlength="253" required placeholder="example.com"></label><label>Category<select v-model="domainRule.category"><option value="work_related">Work related</option><option value="neutral">Neutral</option><option value="review_context">Review with employee context</option><option value="unclassified">Unclassified</option></select></label><label>Reason<input v-model.trim="domainRule.reason" minlength="10" maxlength="500" required></label><button :disabled="busy || !report.cohort.key">Save domain rule</button></form></section><form v-if="admin&&!report.published" class="card" @submit.prevent="publish"><h2>Review and publish</h2><p>Completion {{report.metrics.completion ?? '—'}} · Quality {{report.metrics.quality ?? '—'}} · Deadlines {{report.metrics.deadlines ?? '—'}}</p><label>Collaboration (0–100)<input v-model.number="review.collaboration" type="number" min="0" max="100" required></label><label>Evidence for collaboration and overall review<textarea v-model.trim="review.manager_note" minlength="20" maxlength="2000" required></textarea></label><p><strong>Preview: {{preview ?? 'Insufficient data'}}{{preview?' / 100':''}}</strong></p><label class="check-label"><input v-model="review.confirmed" type="checkbox" required>I reviewed the outcomes, scoring rules and employee explanations. Publish this final snapshot to the employee.</label><button class="primary" :disabled="busy || !report.eligible || !review.confirmed">Publish reviewed result</button></form>
</template></section></template>
<style scoped>
.performance-workspace{display:grid;grid-template-columns:minmax(0,1fr);gap:20px;min-width:0}.performance-task{padding:20px 0;border-bottom:1px solid #e3e9e8}.performance-task:last-child{border:0}.performance-note{white-space:pre-wrap;overflow-wrap:anywhere}summary{cursor:pointer;font-weight:650;padding:10px 0}form{display:grid;gap:12px}h3{margin:0}.performance-workspace input[type=number]{max-width:200px}.performance-workspace .stats-grid{margin:0}.performance-workspace details p{line-height:1.6}
.performance-workspace>*{min-width:0}.performance-workspace .stats-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.performance-workspace .form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.performance-workspace .stat{min-width:0;overflow-wrap:anywhere}@media(max-width:850px){.performance-workspace .stats-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.performance-workspace .form-grid{grid-template-columns:minmax(0,1fr)}.performance-workspace .card-heading{flex-wrap:wrap;gap:10px}.performance-workspace .stat{padding:16px}.performance-workspace .stat strong{font-size:25px}}
.performance-workspace table{min-width:640px}
</style>




